def match(orders):
    import heapq

    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    info = {}       # id -> dict(side, price, qty, active, seq)
    trades = []
    seq_counter = 0

    for o in orders:
        if o[0] == 'cancel':
            oid = o[1]
            if oid in info:
                rec = info[oid]
                if rec['active'] and rec['qty'] > 0:
                    rec['active'] = False
            continue

        typ = o[0]
        oid = o[1]
        side = o[2]

        if typ == 'market':
            price = None
            qty = o[3]
        else:
            price = o[3]
            qty = o[4]

        seq_counter += 1
        seq = seq_counter
        rec = {'side': side, 'price': price, 'qty': qty, 'active': True, 'seq': seq}
        info[oid] = rec

        remaining = qty

        if side == 'buy':
            opp = sell_heap
        else:
            opp = buy_heap

        while remaining > 0 and opp:
            top_entry = opp[0]
            top_stored_price, top_seq, top_id = top_entry
            top_rec = info[top_id]

            if not top_rec['active'] or top_rec['qty'] <= 0:
                heapq.heappop(opp)
                continue

            if side == 'buy':
                actual_resting_price = top_stored_price  # sell heap stores actual price
                if price is not None and actual_resting_price > price:
                    break
            else:
                actual_resting_price = -top_stored_price  # buy heap stores negative price
                if price is not None and actual_resting_price < price:
                    break

            trade_qty = min(remaining, top_rec['qty'])

            if side == 'buy':
                trades.append([oid, top_id, actual_resting_price, trade_qty])
            else:
                trades.append([top_id, oid, actual_resting_price, trade_qty])

            remaining -= trade_qty
            top_rec['qty'] -= trade_qty

            heapq.heappop(opp)
            if top_rec['qty'] > 0:
                heapq.heappush(opp, (top_stored_price, top_seq, top_id))
            else:
                top_rec['active'] = False

        rec['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            rec['active'] = False

    return trades

